-- 队列基础：牺牲槽位、size 或标志位区分空与满。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '循环队列判空、判满与长度','牺牲一个槽位时 front=rear 为空，(rear+1) mod m=front 为满，最多保存 m-1 个元素。',course.id,parent.id,'cs408-circular-queue-state','AISTU',1,'REVIEWED',10,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-circular-queue-state' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-circular-queue-state',1,'REVIEWED','循环队列判空、判满与长度',JSON_OBJECT('summary','循环队列必须明确区分 front=rear 的空与满。牺牲一个槽位时，front=rear 表示空，(rear+1) mod m=front 表示满，长度为 (rear-front+m) mod m，最多存 m-1 个元素；使用 size 时可存 m 个，但每次操作都要同步更新。','steps',JSON_ARRAY('先选择牺牲槽位、size 或标志位约定','牺牲槽位时 front=rear 表示空','下一 rear 等于 front 表示满','长度按 (rear-front+m) mod m 计算','不同约定的判空判满公式不可混用'),'visualization',JSON_OBJECT('kind','ARRAY_QUEUE_REPRESENTATION','version',1,'capacity',6,'headIndex',4,'elements',JSON_ARRAY('A','B','C')),'prerequisite',JSON_OBJECT('contentKey','cs408-circular-queue-representation','title','循环队列的数组表示','description','先理解 front、rear 与模运算回绕。'),'nextStep',JSON_OBJECT('contentKey','cs408-linked-queue','title','链队列','description','继续比较无需固定数组容量的链式实现。')),JSON_OBJECT('id','circular-queue-state-v1','prompt','牺牲一个槽位的循环队列中，判满条件是什么？','options',JSON_ARRAY(JSON_OBJECT('id','ONE_EMPTY_SLOT','text','(rear+1) mod m = front'),JSON_OBJECT('id','FRONT_EQUALS_REAR','text','front = rear')),'correctOptionId','ONE_EMPTY_SLOT','correctExplanation','正确：预留一个空槽后，rear 的下一位置追上 front 即表示满。','incorrectExplanation','不正确：在牺牲槽位约定中，front=rear 表示空。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-circular-queue-state' AND existing.content_version=1 WHERE point.content_key='cs408-circular-queue-state' AND existing.id IS NULL;
